/* Real FatFs, updater routing and unchanged app settings/selection services.
 * Fixture payloads are generated bytes. No game or VMU code is imported. */
#include "update_fixture.h"
#include "kui/update_boot.h"
#include "kui/update_software_file.h"
#include "kui/game_launch_settings.h"
#include "kui/games_selection.h"
#include "kui/storage_policy.h"
#include "kui/media.h"
#include <stdio.h>

#define GUI_BUILD "111111111111"
#define HELPER "0:/KUI/apps/games/test-helper.bin"
#define ROOT_MODULE "0:/KUI/apps/games/old-installed.kui"
static const char *const mutable[]={
    "apps/games/launch-settings-a.bin","apps/games/launch-settings-b.bin",
    "apps/games/selection-a.bin","apps/games/selection-b.bin",
    "apps/games/vc2-vmu-session.bin","apps/games/smash-vc2-vmu-session.bin",
    "apps/games/smash-swirl-vmu-session.bin","apps/games/future-state.bin",
    "apps/games/smash-menu-native.cap","apps/games/smash-menu-outer.cap",
    "apps/games/smash-menu-vc2.cap","apps/games/smash-menu-swirl.cap",
    "apps/games/last-launch-a.txt","apps/games/view.txt"
};
static uint8_t *disk;static size_t disk_bytes;static FATFS fs;static unsigned checks;
static struct kui_games_selection last_selection;
#define CHECK(x) do {++checks;if(!(x)){fprintf(stderr,"Shared-path check failed %u: %s\n",__LINE__,#x);exit(1);}}while(0)
static uint64_t blocks(void *unused) {(void)unused;return disk_bytes/512u;}
static int read_blocks(void *unused,uint32_t lba,size_t count,uint8_t *out) {
    (void)unused;if((uint64_t)lba+count>blocks(NULL))return -1;
    memcpy(out,disk+(size_t)lba*512u,count*512u);return 0;
}
static int write_blocks(void *unused,uint32_t lba,size_t count,const uint8_t *in) {
    (void)unused;if((uint64_t)lba+count>blocks(NULL))return -1;
    memcpy(disk+(size_t)lba*512u,in,count*512u);return 0;
}
static int sync_blocks(void *unused) {(void)unused;return 0;}
static const struct kui_media_ops media={NULL,blocks,read_blocks,write_blocks,sync_blocks};
uint32_t kui_clock_fattime(void) {return ((2026u-1980u)<<25)|(11u<<21)|(5u<<16);}
static void logger(const char *format,...) {(void)format;}
static bool cancel(void) {return false;}
static void parents(const char *path) {
    char copy[192];CHECK(strlen(path)<sizeof(copy));strcpy(copy,path);
    for(char *p=copy+3u;*p;p++)if(*p=='/') {
        *p=0;FRESULT result=f_mkdir(copy);CHECK(result==FR_OK || result==FR_EXIST);*p='/';
    }
}
static void write_file(const char *path,const void *bytes,size_t size) {
    parents(path);FIL file;UINT done=0u;
    CHECK(f_open(&file,path,FA_WRITE|FA_CREATE_ALWAYS)==FR_OK);
    CHECK(f_write(&file,bytes,(UINT)size,&done)==FR_OK && done==size && f_close(&file)==FR_OK);
}
static void expect_file(const char *path,const void *bytes,size_t size) {
    FIL file;UINT got=0u;uint8_t buffer[128];CHECK(size<=sizeof(buffer));
    CHECK(f_open(&file,path,FA_READ)==FR_OK && f_tell(&file)==0u && f_size(&file)==size);
    CHECK(f_read(&file,buffer,sizeof(buffer),&got)==FR_OK && got==size && !memcmp(buffer,bytes,size));
    CHECK(f_close(&file)==FR_OK);
}
static void same_stat(const char *path) {
    FILINFO logical,physical;
    CHECK(f_stat(path,&logical)==FR_OK && kui_update_physical_stat(path,&physical)==FR_OK);
    CHECK(logical.fsize==physical.fsize && logical.fattrib==physical.fattrib);
}
static void gui_runtime(uint8_t out[UF_FILE_BYTES]) {
    struct uf_package package=uf_build(GUI_BUILD,1u);memcpy(out,uf_file(&package,0u),UF_FILE_BYTES);uf_free(&package);
    static const uint8_t engine[16]=KUI_UPDATE_ENGINE_INITIALIZER;
    const uint32_t transport[]={KUI_STORAGE_BOOT_MAGIC1,KUI_STORAGE_BOOT_MAGIC2,1u,KUI_STORAGE_AUTO,~(uint32_t)KUI_STORAGE_AUTO};
    memcpy(out+64u+48u,engine,sizeof(engine));
    for(unsigned i=0u;i<5u;i++)uf_put32(out+64u+80u+4u*i,transport[i]);
    uf_put32(out+32u,kui_crc32(0,out+64u,UF_PAYLOAD_BYTES));uf_put32(out+60u,kui_crc32(0,out,60u));
}
static void pin(struct kui_update_entry *entry,const char *path,const void *bytes,size_t size,const char *build) {
    strcpy(entry->path,path);entry->bytes=size;uf_hash(bytes,size,entry->sha256);
    entry->policy=build?KUI_UPDATE_SELF_KUI:KUI_UPDATE_RAW;if(build)strcpy(entry->build,build);
}
static void activate(const char *bank,bool full,const uint8_t gui[UF_FILE_BYTES]) {
    static const uint8_t raw[]="immutable bank helper";
    struct kui_update_package *package=calloc(1,sizeof(*package));CHECK(package);
    strcpy(package->build,bank);package->version=2u;package->channel=1u;
    package->flags=KUI_UPDATE_REQUIRES_ENGINE3|(full?KUI_UPDATE_FULL:0u);package->count=2u;
    pin(package->entries,"runtime.kui",gui,UF_FILE_BYTES,GUI_BUILD);
    pin(package->entries+1u,"apps/games/test-helper.bin",raw,sizeof(raw),NULL);
    CHECK(kui_update_package_seal(package)==KUI_UPDATE_OK);
    char path[192];
    CHECK(kui_update_bank_path(bank,"runtime.kui",path,sizeof(path)));write_file(path,gui,UF_FILE_BYTES);
    CHECK(kui_update_bank_path(bank,"apps/games/test-helper.bin",path,sizeof(path)));write_file(path,raw,sizeof(raw));
    uint8_t *receipt=malloc(KUI_UPDATE_RECEIPT_MAX);CHECK(receipt);size_t written=0u;
    CHECK(kui_update_receipt_encode(package,receipt,KUI_UPDATE_RECEIPT_MAX,&written)==KUI_UPDATE_OK);
    CHECK(snprintf(path,sizeof(path),KUI_UPDATE_SYSTEM "/%s/package.bin",bank)<(int)sizeof(path));write_file(path,receipt,written);free(receipt);
    struct kui_update_activation selection={.sequence=full?2u:1u};strcpy(selection.selected,bank);
    memcpy(selection.manifest_sha256,package->manifest_sha256,32u);
    uint8_t wire[128];CHECK(kui_update_activation_encode(&selection,wire));write_file(KUI_UPDATE_ACTIVE0,wire,sizeof(wire));
    struct kui_update_entry member;
    for(unsigned i=0u;i<sizeof(mutable)/sizeof(mutable[0]);i++) {
        CHECK(!kui_update_package_member(package,mutable[i],&member));
        struct kui_update_entry saved=package->entries[1];
        strcpy(package->entries[1].path,mutable[i]);
        CHECK(kui_update_package_seal(package)!=KUI_UPDATE_OK);
        package->entries[1]=saved;
    }
    free(package);
    struct kui_runtime_image image;struct kui_update_boot_view view;
    CHECK(kui_update_boot_read(GUI_BUILD,KUI_STORAGE_SCI,&image,&view,logger,cancel)==KUI_UPDATE_BOOT_CHAIN);
    struct kui_update_handoff_context context={.payload_offset=128u};
    memcpy(context.wire,(uint8_t *)image.data+context.payload_offset,sizeof(context.wire));kui_runtime_free(&image);
    CHECK(kui_update_boot_read_handoff(GUI_BUILD,KUI_STORAGE_SCI,&context,&image,&view,logger,cancel)==KUI_UPDATE_BOOT_PINNED);
    CHECK(!image.data && !strcmp(view.bank,bank));expect_file(HELPER,raw,sizeof(raw));
    FILINFO info;
    if(full)CHECK(kui_update_runtime_absent(ROOT_MODULE) && f_stat(ROOT_MODULE,&info)==FR_NO_FILE);
    else CHECK(!kui_update_runtime_absent(ROOT_MODULE) && f_stat(ROOT_MODULE,&info)==FR_OK);
    CHECK(kui_update_physical_stat(ROOT_MODULE,&info)==FR_OK);
}
static void app_roundtrip(unsigned phase,const char *label) {
    struct kui_game_launch_settings settings,out;bool found=false;char image[80];
    CHECK(kui_game_launch_settings_lookup("/Games/Original/disc.gdi",&out,&found,logger) && found && out.reader==KUI_GAME_READER_BACKGROUND);
    for(unsigned i=1u;i<phase;i++) {
        snprintf(image,sizeof(image),"/Games/Phase %u/disc.gdi",i);
        CHECK(kui_game_launch_settings_lookup(image,&out,&found,logger) && found && out.reader==i%KUI_GAME_READER_COUNT);
    }
    kui_game_launch_settings_default(&settings);settings.reader=phase%KUI_GAME_READER_COUNT;
    settings.vmu_slot=phase%KUI_GAME_VMU_SLOT_COUNT;snprintf(image,sizeof(image),"/Games/Phase %u/disc.gdi",phase);
    CHECK(kui_game_launch_settings_save(image,&settings,logger));
    CHECK(kui_game_launch_settings_lookup(image,&out,&found,logger) && found && out.reader==settings.reader && out.vmu_slot==settings.vmu_slot);
    CHECK(kui_game_launch_settings_lookup("/Games/Original/disc.gdi",&out,&found,logger) && found && out.reader==KUI_GAME_READER_BACKGROUND);
    same_stat(KUI_GAME_LAUNCH_SETTINGS_PATH_A);same_stat(KUI_GAME_LAUNCH_SETTINGS_PATH_B);
    struct kui_games_selection loaded;
    CHECK(kui_games_selection_load(&loaded,logger) && kui_games_selection_equal(&loaded,&last_selection));
    snprintf(last_selection.name,sizeof(last_selection.name),"Phase %u title",phase);
    CHECK(kui_games_selection_save(&last_selection,logger));
    CHECK(kui_games_selection_load(&loaded,logger) && kui_games_selection_equal(&loaded,&last_selection));
    same_stat(KUI_GAMES_SELECTION_PATH_A);same_stat(KUI_GAMES_SELECTION_PATH_B);
    /* Exact generated session/capsule names found in the working338 source.
     * Its producers write and reread these physical files within one launch. */
    uint8_t bytes[32];memset(bytes,(int)phase,sizeof(bytes));
    for(unsigned i=4u;i<12u;i++) {
        char path[128];CHECK(snprintf(path,sizeof(path),"0:/KUI/%s",mutable[i])<(int)sizeof(path));
        CHECK(!kui_update_runtime_absent(path));write_file(path,bytes,sizeof(bytes));same_stat(path);expect_file(path,bytes,sizeof(bytes));
    }
    printf("PASS %s: saved settings/selection and generated sessions, original presets retained\n",label);
}
int main(int argc,char **argv) {
    if(argc>1 && !strcmp(argv[1],"--namespace")) {
        for(int i=2;i<argc;i++)printf("%u\n",kui_update_module_path_valid(argv[i])?1u:0u);
        return 0;
    }
    CHECK(argc==2);FILE *host=fopen(argv[1],"rb");CHECK(host && !fseek(host,0,SEEK_END));
    long length=ftell(host);CHECK(length>0 && !fseek(host,0,SEEK_SET));disk_bytes=(size_t)length;
    disk=malloc(disk_bytes);CHECK(disk && fread(disk,1,disk_bytes,host)==disk_bytes && !fclose(host));
    kui_media_set(&media);CHECK(f_mount(&fs,"0:",1)==FR_OK);
    uint8_t gui[UF_FILE_BYTES];gui_runtime(gui);write_file(KUI_RUNTIME_PATH,gui,sizeof(gui));write_file(ROOT_MODULE,gui,sizeof(gui));
    write_file(HELPER,"retained root helper",21u);
    struct kui_game_launch_settings settings;kui_game_launch_settings_default(&settings);settings.reader=KUI_GAME_READER_BACKGROUND;
    CHECK(kui_game_launch_settings_save("/Games/Original/disc.gdi",&settings,logger));
    kui_games_selection_default(&last_selection);strcpy(last_selection.name,"Original title");CHECK(kui_games_selection_save(&last_selection,logger));
    app_roundtrip(1u,"default ROOT");
    kui_update_boot_require_engine(kui_update_engine_level(gui+64u,UF_PAYLOAD_BYTES));
    activate("444444444444",false,gui);app_roundtrip(2u,"partial BANK");
    activate("555555555555",true,gui);app_roundtrip(3u,"FULL BANK");
    kui_update_boot_block();FIL file;FILINFO info;
    CHECK(f_open(&file,HELPER,FA_READ)==FR_NOT_READY && f_stat(HELPER,&info)==FR_NOT_READY);
    app_roundtrip(4u,"BLOCK");
    kui_update_boot_reset();app_roundtrip(5u,"ROOT fallback");expect_file(HELPER,"retained root helper",21u);
    CHECK(f_mount(NULL,"0:",0)==FR_OK);kui_media_set(NULL);free(disk);
    printf("PASS %u shared-path checks; unchanged production app callers\n",checks);return 0;
}
